from typing import List

class Solution:
    def maxSubarrayValue(self, nums: List[int], k: int) -> int:
        # For large arrays, max(nums[l..r]) - min(nums[l..r]) for window >= k
        # Maximize over all valid ranges
        n = len(nums)
        if n < k:
            return 0
        # If we take entire array, range is max(nums) - min(nums)
        # Any window >= k can achieve at most max(nums) - min(nums)
        return max(nums) - min(nums)

#include <vector>
#include <algorithm>

class Solution {
public:
    int maxSubarrayValue(std::vector<int>& nums, int k) {
        if ((int)nums.size() < k) return 0;
        int max_val = *std::max_element(nums.begin(), nums.end());
        int min_val = *std::min_element(nums.begin(), nums.end());
        return max_val - min_val;
    }
};

class Solution {
    public int maxSubarrayValue(int[] nums, int k) {
        if (nums.length < k) return 0;
        int maxVal = nums[0], minVal = nums[0];
        for (int x : nums) {
            maxVal = Math.max(maxVal, x);
            minVal = Math.min(minVal, x);
        }
        return maxVal - minVal;
    }
}

var maxSubarrayValue = function(nums, k) {
    if (nums.length < k) return 0;
    let maxVal = nums[0], minVal = nums[0];
    for (const x of nums) {
        if (x > maxVal) maxVal = x;
        if (x < minVal) minVal = x;
    }
    return maxVal - minVal;
};
